script:
frappe.call({method: "stockist_dashboard_stats"}).then(r => {
	const d = r.message || {};
	const fmt = n => "₹" + Math.round(n).toLocaleString("en-IN");
	root_element.getElementById("sk-new-orders").textContent = d.new_orders ?? "--";
	root_element.getElementById("sk-today-sales").textContent = fmt(d.today_sales || 0);
	root_element.getElementById("sk-total-dues").textContent = fmt(d.total_dues || 0);
	root_element.getElementById("sk-active-customers").textContent = d.active_customers ?? "--";
	root_element.getElementById("sk-total-customers").textContent = "of " + (d.total_customers ?? "--") + " total";
});

const btn = root_element.getElementById("sk-sync-btn");
const status = document.createElement("div");
status.id = "sk-sync-status";
status.style.cssText = "font-size:12px;color:#888;margin-top:6px;";
btn.parentElement.parentElement.appendChild(status);

frappe.realtime.on("kirana_console_sync_done", (r) => {
	btn.disabled = false;
	btn.textContent = "Sync Now";
	if (r.status === "success") {
		status.style.color = "#2a8";
		status.textContent = r.summary;
	} else {
		status.style.color = "#c33";
		status.textContent = "Sync failed: " + r.message;
	}
});

btn.onclick = () => {
	btn.disabled = true;
	btn.textContent = "Syncing...";
	status.style.color = "#888";
	status.textContent = "This can take a couple of minutes for a full catalog.";
	frappe.call({ method: "kirana_console.sync.sync_now" }).catch(() => {
		btn.disabled = false;
		btn.textContent = "Sync Now";
	});
};

(function () {
	let DATA = { active: [], not_onboarded: [], needs_review: [] };
	let TAB = "active";

	const fmt = n => "₹" + Math.round(n || 0).toLocaleString("en-IN");
	const tbody = root_element.getElementById("sk-cust-tbody");
	const thead = root_element.getElementById("sk-cust-thead");
	const empty = root_element.getElementById("sk-cust-empty");
	const search = root_element.getElementById("sk-cust-search");

	function showPin(mobile, pin) {
		root_element.getElementById("sk-pin-mobile").textContent = mobile;
		root_element.getElementById("sk-pin-value").textContent = pin;
		root_element.getElementById("sk-pin-modal").style.display = "flex";
	}
	root_element.getElementById("sk-pin-close").onclick = () => {
		root_element.getElementById("sk-pin-modal").style.display = "none";
		load();
	};

	function btn(label, color) {
		return `<button class="sk-act" style="padding:5px 10px;font-size:12px;border-radius:5px;border:1px solid ${color};background:#fff;color:${color};cursor:pointer;margin-right:4px;">${label}</button>`;
	}

	function render() {
		const rows = DATA[TAB] || [];
		const q = (search.value || "").toLowerCase().trim();
		const filtered = q
			? rows.filter(r => (r.customer_name || "").toLowerCase().includes(q) || (r.mobile_no || "").includes(q))
			: rows;

		root_element.querySelectorAll(".sk-tab-btn").forEach(b => {
			const active = b.dataset.tab === TAB;
			b.style.background = active ? "#3E2417" : "#fff";
			b.style.color = active ? "#fff" : "#3E2417";
		});

		if (TAB === "active") {
			thead.innerHTML = "<th style='text-align:left;padding:8px;'>Shop</th><th style='text-align:left;padding:8px;'>Mobile</th><th style='text-align:left;padding:8px;'>Due</th><th style='text-align:left;padding:8px;'>Status</th><th style='padding:8px;'>Actions</th>";
			tbody.innerHTML = filtered.map(r => `
				<tr style="border-top:1px solid #eee;">
					<td style="padding:8px;">${r.customer_name}</td>
					<td style="padding:8px;">${r.mobile_no || "-"}</td>
					<td style="padding:8px;">${fmt(r.due)}</td>
					<td style="padding:8px;">${r.status === "active" ? "<span style='color:#2a8;'>Active</span>" : "<span style='color:#c33;'>Revoked</span>"}</td>
					<td style="padding:8px;white-space:nowrap;">
						${btn("Reset PIN", "#3E2417")}
						${r.status === "active" ? btn("Revoke", "#c33") : btn("Restore", "#2a8")}
					</td>
				</tr>`).join("");
			tbody.querySelectorAll("tr").forEach((tr, i) => {
				const r = filtered[i];
				const [resetBtn, toggleBtn] = tr.querySelectorAll(".sk-act");
				resetBtn.onclick = () => frappe.call({ method: "stockist_reset_pin", args: { customer: r.customer } })
					.then(res => showPin(res.message.mobile_no, res.message.pin));
				toggleBtn.onclick = () => frappe.call({ method: "stockist_toggle_access", args: { customer: r.customer, enable: r.status === "active" ? 0 : 1 } })
					.then(() => load());
			});
		} else if (TAB === "not_onboarded") {
			thead.innerHTML = "<th style='text-align:left;padding:8px;'>Shop</th><th style='text-align:left;padding:8px;'>Mobile</th><th style='padding:8px;'>Actions</th>";
			tbody.innerHTML = filtered.map(r => `
				<tr style="border-top:1px solid #eee;">
					<td style="padding:8px;">${r.customer_name}</td>
					<td style="padding:8px;">${r.mobile_no ? r.mobile_no : "<input type='tel' class='sk-mobile-input' placeholder='Enter mobile number' style='padding:4px;border:1px solid #ccc;border-radius:4px;width:130px;'>"}</td>
					<td style="padding:8px;">${btn("Grant Access", "#3E2417")}</td>
				</tr>`).join("");
			tbody.querySelectorAll("tr").forEach((tr, i) => {
				const r = filtered[i];
				const grantBtn = tr.querySelector(".sk-act");
				const input = tr.querySelector(".sk-mobile-input");
				grantBtn.onclick = () => {
					const mobile = r.mobile_no || (input && input.value.trim());
					if (!mobile) { frappe.msgprint("Enter a mobile number first."); return; }
					frappe.call({ method: "stockist_grant_access", args: { customer: r.customer, mobile_no: mobile } })
						.then(res => showPin(res.message.mobile_no, res.message.pin));
				};
			});
		} else {
			thead.innerHTML = "<th style='text-align:left;padding:8px;'>Shop</th><th style='text-align:left;padding:8px;'>Mobile</th><th style='text-align:left;padding:8px;'>Due</th>";
			tbody.innerHTML = filtered.map(r => `
				<tr style="border-top:1px solid #eee;">
					<td style="padding:8px;">${r.customer_name}</td>
					<td style="padding:8px;">${r.mobile_no || "-"}</td>
					<td style="padding:8px;">${fmt(r.due)}</td>
				</tr>`).join("");
		}
		empty.style.display = filtered.length ? "none" : "block";
		root_element.getElementById("sk-cust-table-wrap").style.display = filtered.length ? "block" : "none";
	}

	function load() {
		frappe.call({ method: "stockist_customer_access_list" }).then(r => {
			DATA = r.message || DATA;
			render();
		});
	}

	root_element.querySelectorAll(".sk-tab-btn").forEach(b => {
		b.onclick = () => { TAB = b.dataset.tab; render(); };
	});
	search.oninput = render;

	load();
})();

(function () {
	let ITEMS = [];
	let EDITING = null;

	const tbody = root_element.getElementById("sk-prod-tbody");
	const empty = root_element.getElementById("sk-prod-empty");
	const search = root_element.getElementById("sk-prod-search");
	const modal = root_element.getElementById("sk-prod-modal");
	const fmt = n => "₹" + Math.round(n || 0).toLocaleString("en-IN");

	function openModal(item) {
		EDITING = item;
		root_element.getElementById("sk-prod-edit-name").value = item.item_name || "";
		root_element.getElementById("sk-prod-edit-price").value = item.price || 0;
		root_element.getElementById("sk-prod-edit-group").value = item.item_group || "";
		modal.style.display = "flex";
	}
	root_element.getElementById("sk-prod-cancel").onclick = () => { modal.style.display = "none"; };
	root_element.getElementById("sk-prod-save").onclick = () => {
		const name = root_element.getElementById("sk-prod-edit-name").value.trim();
		const price = parseFloat(root_element.getElementById("sk-prod-edit-price").value);
		const group = root_element.getElementById("sk-prod-edit-group").value.trim();
		frappe.call({
			method: "stockist_update_product",
			args: { item_code: EDITING.item_code, item_name: name, price: price, item_group: group },
		}).then(() => {
			modal.style.display = "none";
			load();
		});
	};

	function btn(label, color) {
		return `<button class="sk-act" style="padding:5px 10px;font-size:12px;border-radius:5px;border:1px solid ${color};background:#fff;color:${color};cursor:pointer;margin-right:4px;">${label}</button>`;
	}

	function render() {
		const q = (search.value || "").toLowerCase().trim();
		const filtered = q
			? ITEMS.filter(r => (r.item_name || "").toLowerCase().includes(q) || (r.brand || "").toLowerCase().includes(q))
			: ITEMS;

		tbody.innerHTML = filtered.slice(0, 200).map(r => `
			<tr style="border-top:1px solid #eee;">
				<td style="padding:8px;">${r.item_name}${r.overridden ? " <span style='color:#EE8B1D;font-size:11px;'>(edited)</span>" : ""}</td>
				<td style="padding:8px;">${r.item_group}</td>
				<td style="padding:8px;">${fmt(r.price)}</td>
				<td style="padding:8px;">${r.active ? "<span style='color:#2a8;'>Active</span>" : "<span style='color:#c33;'>Inactive</span>"}</td>
				<td style="padding:8px;white-space:nowrap;">
					${btn("Edit", "#3E2417")}
					${r.active ? btn("Deactivate", "#c33") : btn("Activate", "#2a8")}
				</td>
			</tr>`).join("");

		tbody.querySelectorAll("tr").forEach((tr, i) => {
			const r = filtered[i];
			const [editBtn, toggleBtn] = tr.querySelectorAll(".sk-act");
			editBtn.onclick = () => openModal(r);
			toggleBtn.onclick = () => frappe.call({
				method: "stockist_update_product",
				args: { item_code: r.item_code, active: r.active ? 0 : 1 },
			}).then(() => load());
		});

		empty.style.display = filtered.length ? "none" : "block";
		root_element.getElementById("sk-prod-table-wrap").style.display = filtered.length ? "block" : "none";
		if (filtered.length > 200) {
			const note = document.createElement("tr");
			note.innerHTML = `<td colspan="5" style="padding:8px;text-align:center;color:#999;font-size:12px;">Showing first 200 of ${filtered.length} - narrow your search to see more.</td>`;
			tbody.appendChild(note);
		}
	}

	function load() {
		frappe.call({ method: "stockist_products_list" }).then(r => {
			ITEMS = (r.message && r.message.items) || [];
			render();
		});
	}

	search.oninput = render;
	load();
})();

(function () {
	// ---- tabs ----
	root_element.querySelectorAll(".sk-mkt-tab").forEach(function (b) {
		b.onclick = function () {
			root_element.querySelectorAll(".sk-mkt-tab").forEach(function (x) {
				x.style.background = "#fff"; x.style.color = "#3E2417";
			});
			b.style.background = "#3E2417"; b.style.color = "#fff";
			root_element.getElementById("sk-mkt-announcements").style.display = b.dataset.tab === "announcements" ? "block" : "none";
			root_element.getElementById("sk-mkt-coupons").style.display = b.dataset.tab === "coupons" ? "block" : "none";
		};
	});

	// ---- announcements ----
	function annBtn(label, color) {
		return `<button class="sk-ann-act" style="padding:5px 10px;font-size:12px;border-radius:5px;border:1px solid ${color};background:#fff;color:${color};cursor:pointer;">${label}</button>`;
	}
	function loadAnnouncements() {
		frappe.call({ method: "stockist_announcements_list" }).then(function (r) {
			var rows = (r.message && r.message.announcements) || [];
			var tbody = root_element.getElementById("sk-ann-tbody");
			tbody.innerHTML = rows.map(function (a) {
				return `<tr style="border-top:1px solid #eee;">
					<td style="padding:8px;">${a.title}</td>
					<td style="padding:8px;">${a.announcement_type}</td>
					<td style="padding:8px;max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${a.message}</td>
					<td style="padding:8px;">${a.is_active ? "<span style='color:#2a8;'>Active</span>" : "<span style='color:#c33;'>Off</span>"}</td>
					<td style="padding:8px;">${annBtn(a.is_active ? "Turn Off" : "Turn On", a.is_active ? "#c33" : "#2a8")}</td>
				</tr>`;
			}).join("");
			tbody.querySelectorAll("tr").forEach(function (tr, i) {
				var a = rows[i];
				tr.querySelector(".sk-ann-act").onclick = function () {
					frappe.call({ method: "stockist_toggle_announcement", args: { name: a.name, enable: a.is_active ? 0 : 1 } }).then(loadAnnouncements);
				};
			});
		});
	}
	root_element.getElementById("sk-ann-new").onclick = function () {
		root_element.getElementById("sk-ann-title").value = "";
		root_element.getElementById("sk-ann-message").value = "";
		root_element.getElementById("sk-ann-end").value = "";
		root_element.getElementById("sk-ann-modal").style.display = "flex";
	};
	root_element.getElementById("sk-ann-cancel").onclick = function () {
		root_element.getElementById("sk-ann-modal").style.display = "none";
	};
	root_element.getElementById("sk-ann-save").onclick = function () {
		var title = root_element.getElementById("sk-ann-title").value.trim();
		var type = root_element.getElementById("sk-ann-type").value;
		var message = root_element.getElementById("sk-ann-message").value.trim();
		var end = root_element.getElementById("sk-ann-end").value;
		if (!title || !message) { frappe.msgprint("Title and message are required."); return; }
		frappe.call({
			method: "stockist_create_announcement",
			args: { title: title, announcement_type: type, message: message, end_date: end || null },
		}).then(function () {
			root_element.getElementById("sk-ann-modal").style.display = "none";
			loadAnnouncements();
		});
	};

	// ---- coupons ----
	function couponBtn(label, color) {
		return `<button class="sk-coupon-act" style="padding:5px 10px;font-size:12px;border-radius:5px;border:1px solid ${color};background:#fff;color:${color};cursor:pointer;">${label}</button>`;
	}
	function loadCoupons() {
		frappe.call({ method: "stockist_coupons_list" }).then(function (r) {
			var rows = (r.message && r.message.coupons) || [];
			var tbody = root_element.getElementById("sk-coupon-tbody");
			tbody.innerHTML = rows.map(function (c) {
				return `<tr style="border-top:1px solid #eee;">
					<td style="padding:8px;font-weight:600;">${c.code}</td>
					<td style="padding:8px;">${c.discount}</td>
					<td style="padding:8px;">${c.used}${c.max_use ? " / " + c.max_use : ""}</td>
					<td style="padding:8px;">${c.active ? "<span style='color:#2a8;'>Active</span>" : "<span style='color:#c33;'>Off</span>"}</td>
					<td style="padding:8px;">${couponBtn(c.active ? "Turn Off" : "Turn On", c.active ? "#c33" : "#2a8")}</td>
				</tr>`;
			}).join("");
			tbody.querySelectorAll("tr").forEach(function (tr, i) {
				var c = rows[i];
				tr.querySelector(".sk-coupon-act").onclick = function () {
					frappe.call({ method: "stockist_toggle_coupon", args: { name: c.name, enable: c.active ? 0 : 1 } }).then(loadCoupons);
				};
			});
		});
	}
	root_element.getElementById("sk-coupon-new").onclick = function () {
		root_element.getElementById("sk-coupon-code").value = "";
		root_element.getElementById("sk-coupon-value").value = "";
		root_element.getElementById("sk-coupon-max").value = "0";
		root_element.getElementById("sk-coupon-modal").style.display = "flex";
	};
	root_element.getElementById("sk-coupon-cancel").onclick = function () {
		root_element.getElementById("sk-coupon-modal").style.display = "none";
	};
	root_element.getElementById("sk-coupon-save").onclick = function () {
		var code = root_element.getElementById("sk-coupon-code").value.trim().toUpperCase();
		var type = root_element.getElementById("sk-coupon-type").value;
		var value = root_element.getElementById("sk-coupon-value").value;
		var max = root_element.getElementById("sk-coupon-max").value;
		if (!code || !value) { frappe.msgprint("Code and discount value are required."); return; }
		frappe.call({
			method: "stockist_create_coupon",
			args: { code: code, discount_type: type, discount_value: value, max_use: max },
		}).then(function () {
			root_element.getElementById("sk-coupon-modal").style.display = "none";
			loadCoupons();
		});
	};

	loadAnnouncements();
	loadCoupons();
})();
